window.GW_GHOST_PRE["ml"] = {"welcomeT":"GHOSTWALK-ലേക്ക് സ്വാഗതം","welcomeV":"ഈ സേവനം ഉപയോഗിക്കുമ്പോൾ നിങ്ങൾക്ക് വോയ്‌സ് ഗൈഡൻസ് വേണോ?","hear":"ഈ സന്ദേശം കേൾക്കൂ","whichLang":"നിങ്ങൾ ഇഷ്ടപ്പെടുന്ന ഭാഷ തിരഞ്ഞെടുക്കുക.","moreLangs":"കൂടുതൽ ഭാഷകൾ...","voiceQ":"നിങ്ങൾക്ക് വോയ്‌സ് ഗൈഡൻസും വേണോ?","voiceOn":"വോയ്സ് ഗൈഡൻസ് പ്രവർത്തനക്ഷമമാക്കുക","voiceOff":"വാചകം മാത്രം ഉപയോഗിച്ച് തുടരുക","allSet":"എല്ലാം തയ്യാറായി. ഞാൻ ഇവിടെ മൂലയിൽ നിൽക്കും — നിങ്ങൾക്ക് സഹായം ആവശ്യമുള്ളപ്പോഴെല്ലാം എന്നെ ടാപ്പ് ചെയ്യുക.","close":"അടയ്ക്കുക","back":"← തിരികെ","mute":"🔇 ശബ്ദം നിശബ്ദമാക്കുക","unmute":"🔊 വോയ്സ് ഓഫ് - പ്രവർത്തനക്ഷമമാക്കാൻ ടാപ്പ് ചെയ്യുക","voiceNA":"ഈ ഉപകരണത്തിൽ ഈ ഭാഷയ്‌ക്ക് ശബ്‌ദ മാർഗ്ഗനിർദ്ദേശം ലഭ്യമല്ല. ടെക്‌സ്‌റ്റ് മാർഗ്ഗനിർദ്ദേശം തുടരും.","pause":"⏸ താൽക്കാലികമായി നിർത്തുക","resume":"▶ പുനരാരംഭിക്കുക","repeat":"🔁 ആവർത്തിക്കുക","disableV":"ശബ്ദം പ്രവർത്തനരഹിതമാക്കുക","enableV":"ശബ്ദം പ്രവർത്തനക്ഷമമാക്കുക","changeL":"ഭാഷ മാറ്റുക","replay":"മാർഗ്ഗനിർദ്ദേശം ആവർത്തിക്കുക","curL":"നിലവിലെ ഭാഷ:","menuTitle":"എനിക്ക് എങ്ങനെ സഹായിക്കാനാകും?","tGuide":"ഈ പേജിലൂടെ എന്നെ നയിക്കുക","tExplain":"ഈ ഓപ്ഷൻ വിശദീകരിക്കുക","tRepeat":"അവസാന നിർദ്ദേശം ആവർത്തിക്കുക","actWhatIsThis":"ഇത് എന്താണ്?","actWhatNext":"ഞാൻ ഇപ്പോൾ എന്താണ് ചെയ്യേണ്ടത്?","repeatNone":"ഇതുവരെ ആവർത്തിക്കാൻ നേരത്തെയുള്ള നിർദ്ദേശമില്ല.","tVoiceOn":"വോയ്‌സ് ഗൈഡൻസ് ഓണാണ്","tVoiceOff":"വോയ്‌സ് ഗൈഡൻസ് ഓഫാണ്","tMin":"ചെറുതാക്കുക","tFull":"പൂർണ്ണ അസിസ്റ്റൻ്റ് തുറക്കുക","tNext":"അടുത്തത്","tPrev":"തിരികെ","tEnd":"അവസാന ഗൈഡ്","tYes":"അതെ, എന്നെ നയിക്കൂ","tNotNow":"ഇപ്പോൾ വേണ്ട","guideOffer":"ഈ ഓപ്ഷനുകളിലേക്കുള്ള ഒരു ദ്രുത ഗൈഡ് നിങ്ങൾക്ക് വേണോ?","g_check":"സംശയാസ്പദമായ സന്ദേശം ഇവിടെ ഒട്ടിക്കുക, അല്ലെങ്കിൽ നിങ്ങൾക്കത് സ്ക്രീൻഷോട്ടായോ ഡോക്യുമെൻ്റായോ ലഭിച്ചിട്ടുണ്ടെങ്കിൽ അപ്‌ലോഡ് ഓപ്ഷൻ ഉപയോഗിക്കുക. പാസ്‌വേഡുകളോ OTPകളോ ബാങ്കിംഗ് ക്രെഡൻഷ്യലുകളോ ഉൾപ്പെടുത്തരുത്. ഉള്ളടക്കം തയ്യാറായിക്കഴിഞ്ഞാൽ, ചുവടെയുള്ള വിശകലന ബട്ടൺ തിരഞ്ഞെടുക്കുക.","g_walk":"ആരെങ്കിലും നിങ്ങൾക്ക് സംശയാസ്പദമായ നിക്ഷേപ ലിങ്ക് അയച്ചാൽ, അത് തുറക്കാതെ തന്നെ പകർത്തി ഈ ബോക്സിൽ ഒട്ടിക്കുക. നിങ്ങൾ തയ്യാറാകുമ്പോൾ, \"അന്വേഷണം ആരംഭിക്കുക\" തിരഞ്ഞെടുക്കുക. GHOSTWALK ലക്ഷ്യസ്ഥാനം പ്രത്യേകം പരിശോധിക്കാനും അത് നിരീക്ഷിച്ച സ്വഭാവം തിരികെ നൽകാനും ശ്രമിക്കും.","g_qr":"പൂർണ്ണമായ QR കോഡ് അടങ്ങിയ ഒരു ഫോട്ടോ അല്ലെങ്കിൽ സ്ക്രീൻഷോട്ട് തിരഞ്ഞെടുക്കുക. പേയ്‌മെൻ്റ് ആപ്ലിക്കേഷൻ ഉപയോഗിച്ച് നിങ്ങൾ ഇത് സ്കാൻ ചെയ്യേണ്ടതില്ല. ചിത്രം തിരഞ്ഞെടുത്ത ശേഷം, പ്രിവ്യൂ പരിശോധിച്ച് \"ഈ ചിത്രം ഉപയോഗിക്കുക\" തിരഞ്ഞെടുക്കുക.","g_trusted":"ആദ്യം സംഗ്രഹം അവലോകനം ചെയ്യുക. ഇത് സാഹചര്യം കൃത്യമായി വിവരിക്കുന്നുവെങ്കിൽ, നിങ്ങൾ ഉൾപ്പെടാൻ ആഗ്രഹിക്കുന്ന വിശ്വസ്ത വ്യക്തിയെ തിരഞ്ഞെടുക്കുക. GHOSTWALK അവർക്ക് മുന്നറിയിപ്പ് വിവരങ്ങൾ തയ്യാറാക്കും. അയയ്ക്കുന്നതിന് മുമ്പ് അത് പരിശോധിക്കുക.","g_paid":"അധിക പണം അയക്കരുത്. പണമടച്ചത്, എപ്പോൾ എന്നിവ രേഖപ്പെടുത്തിക്കൊണ്ട് ആരംഭിക്കുക. തുടർന്ന് സ്‌ക്രീൻഷോട്ടുകളും പേയ്‌മെൻ്റ് റഫറൻസുകളും സന്ദേശങ്ങളും സംരക്ഷിക്കുക. GHOSTWALK വിവരങ്ങൾ സംഘടിപ്പിക്കുകയും പിന്തുണയ്‌ക്കുന്ന അടുത്ത വീണ്ടെടുക്കൽ ഘട്ടങ്ങൾ കാണിക്കുകയും ചെയ്യും.","g_check_go":"മുകളിൽ സന്ദേശം ടൈപ്പ് ചെയ്യുക അല്ലെങ്കിൽ ഒട്ടിക്കുക, വിശകലനം ആരംഭിക്കാൻ ഈ ബട്ടൺ അമർത്തുക. ഈ ഉപകരണത്തിലെ എല്ലാം പ്രേതം വായിക്കുന്നു - ഒന്നും തുറക്കുകയോ പണമടയ്ക്കുകയോ ഇല്ല.","g_walk_go":"പ്രേതത്തെ ലിങ്ക് താഴേക്ക് അയയ്ക്കാൻ ഈ ബട്ടൺ അമർത്തുക. ഇത് വ്യാജ വിശദാംശങ്ങളുമായി യാത്രാ സെർവർ സൈഡ് നടത്തുകയും സുരക്ഷിതമായി നിർത്തുകയും ചെയ്യുന്നു - നിങ്ങളത് ഒരിക്കലും തുറക്കില്ല.","g_qr_go":"UPI വിശദാംശങ്ങൾ ഒട്ടിച്ചതിന് ശേഷം ഈ ബട്ടൺ അമർത്തുക. പണം എവിടേക്കാണ് പോകുന്നതെന്ന് പ്രേതം ഡീകോഡ് ചെയ്യുകയും പണം സ്വീകരിക്കുന്നയാളെ കാണിക്കുകയും തുകയും മുന്നറിയിപ്പുകളും കാണിക്കുകയും ചെയ്യുന്നു.","g_trusted_go":"അലേർട്ട് തയ്യാറാക്കാൻ ഈ ബട്ടൺ അമർത്തുക. നിങ്ങളുടെ വിശ്വസ്ത വ്യക്തിയുമായി പങ്കിടുന്നതിന് മുമ്പ് പ്രിവ്യൂ ശ്രദ്ധാപൂർവ്വം വായിക്കുക.","g_paid_go":"നിങ്ങളുടെ സംഭവ പാക്ക് നിർമ്മിക്കാൻ ഈ ബട്ടൺ അമർത്തുക. ഇത് നിങ്ങളുടെ ടൈംലൈനും 1930 ഹെൽപ്പ്‌ലൈനിനായി തെളിവുകളും സംഘടിപ്പിക്കുന്നു - വീണ്ടെടുക്കൽ ഒരിക്കലും ഉറപ്പില്ല.","m_start":"ഒറ്റപ്പെട്ട അന്തരീക്ഷത്തിലാണ് ഇപ്പോൾ ലക്ഷ്യസ്ഥാനം പരിശോധിക്കുന്നത്.","m_done":"അന്വേഷണം പൂർത്തിയായി. എനിക്ക് കണ്ടെത്തലുകൾ ഓരോന്നായി വിശദീകരിക്കാൻ കഴിയും.","langChanged":"ഭാഷ മാറി. ഈ ഭാഷയിൽ ഞാൻ നിങ്ങളെ നയിക്കുന്നത് തുടരും.","voiceWelcome":"ഗോസ്റ്റ്വാക്കിലേക്ക് സ്വാഗതം. നിങ്ങളെ നയിക്കാൻ ഞാൻ ഇവിടെയുണ്ട്. എനിക്ക് ഓരോ ഓപ്ഷനും വിശദീകരിക്കാനും അടുത്തതായി എന്തുചെയ്യണമെന്ന് നിങ്ങളെ കാണിക്കാനും കഴിയും.","textWelcome":"GHOSTWALK-ലേക്ക് സ്വാഗതം. നിങ്ങൾക്ക് സഹായം വേണമെങ്കിൽ ഞാൻ ഇവിടെയുണ്ട്. ചെറിയ പ്രേതത്തെയോ മറ്റെന്തെങ്കിലുമോ ടാപ്പ് ചെയ്യുക? വിശദീകരണത്തിനുള്ള ഐക്കൺ.","hintHome":"സഹായം വേണോ? ടാപ്പ് ചെയ്യുക? ഏതെങ്കിലും ഓപ്ഷൻ കൂടാതെ, അല്ലെങ്കിൽ ഒരു ഗൈഡഡ് ടൂറിനായി ഗോസ്റ്റ് തുറക്കുക.","tExplainChoice":"ഞാൻ എന്താണ് വിശദീകരിക്കാൻ നിങ്ങൾ ആഗ്രഹിക്കുന്നത്?","explainName_checkMessage":"ഒരു സന്ദേശം പരിശോധിക്കുക","explainName_walkLink":"ഒരു ലിങ്ക് നടക്കുക","explainName_qr":"QR / UPI ഡീകോഡ് ചെയ്യുക","explainName_trustedContact":"ഞാൻ വിശ്വസിക്കുന്ന ഒരാളെ അറിയിക്കുക","explainName_alreadyPaid":"ഞാൻ ഇതിനകം പണം നൽകി","vLead":"എന്തുകൊണ്ട്, ലളിതമായ വാക്കുകളിൽ ഇതാ.","vReason":"കാരണം {n}:","vExample":"ഉദാഹരണത്തിന്:","vRephrase":"മറ്റൊരു വാക്കിൽ,","vDoubt":"സംശയമുണ്ടെങ്കിൽ, ഇതുവരെ പണം നൽകരുത്. നിങ്ങൾ വിശ്വസിക്കുന്ന ഒരാളോട് ആദ്യം സംസാരിക്കുക.","emptyRead":"ഇതുവരെ ഒന്നും വായിക്കാനില്ല.","translating":"പേജ് വിവർത്തനം ചെയ്യുന്നു - ഒരു നിമിഷം...","netStruggle":"ഈ നെറ്റ്‌വർക്കിൽ വിവർത്തനം ബുദ്ധിമുട്ടുകയാണ് - ഇപ്പോൾ ഇംഗ്ലീഷ് കാണിക്കുന്നു.","qrUpload":"QR ചിത്രം അപ്‌ലോഡ് ചെയ്യുക","qrUploadSub":"QR കോഡ് അടങ്ങിയ ഒരു ഫോട്ടോ അല്ലെങ്കിൽ സ്ക്രീൻഷോട്ട് അപ്ലോഡ് ചെയ്യുക. പേയ്‌മെൻ്റ് ആരംഭിക്കാതെ തന്നെ GHOSTWALK അത് ഡീകോഡ് ചെയ്യും.","qrDrop":"… അല്ലെങ്കിൽ ഇവിടെ ഒരു ചിത്രം വലിച്ചിടുക","qrTakePhoto":"ഫോട്ടോ എടുക്കുക","qrUse":"ഈ ചിത്രം ഉപയോഗിക്കുക","qrChange":"മറ്റൊന്ന് തിരഞ്ഞെടുക്കുക","qrRemove":"നീക്കം ചെയ്യുക","qrNoCode":"ഈ ചിത്രത്തിൽ നിന്ന് ഞങ്ങൾക്ക് ഒരു QR കോഡ് വായിക്കാൻ കഴിഞ്ഞില്ല. മുഴുവൻ QR കോഡും ദൃശ്യമാകുന്ന ഒരു വ്യക്തമായ ചിത്രം പരീക്ഷിക്കുക.","qrTooBig":"ആ ചിത്രം വളരെ വലുതാണ്. 8 MB-യിൽ താഴെയുള്ള ഒരു ചിത്രം തിരഞ്ഞെടുക്കുക.","qrBadFile":"ആ ഫയൽ ഒരു ചിത്രമായി വായിക്കാൻ കഴിഞ്ഞില്ല. ദയവായി ഒരു PNG, JPG അല്ലെങ്കിൽ WebP സ്ക്രീൻഷോട്ട് തിരഞ്ഞെടുക്കുക.","qrType":"ടൈപ്പ് ചെയ്യുക","qrUpi":"UPI പേയ്‌മെൻ്റ് അഭ്യർത്ഥന","qrUrl":"വെബ് ലിങ്ക്","qrText":"വാചകം","qrPayee":"പണം സ്വീകരിക്കുന്നയാൾ / UPI ഐഡി","qrName":"പേര്","qrAmount":"തുക","qrNote":"കുറിപ്പ് / റഫറൻസ്","qrDecodeUpi":"പേയ്‌മെൻ്റ് ഉദ്ദേശം ഡീകോഡ് ചെയ്യുക","qrInvestigate":"ഈ ലിങ്ക് സുരക്ഷിതമായി അന്വേഷിക്കുക","qrFoundTitle":"QR കണ്ടെത്തി","qrGuideSteps":"ഒരു സാമ്പിൾ ക്യുആർ ചിത്രം ലോഡ് ചെയ്‌തു. ചിത്രത്തിൻ്റെ പ്രിവ്യൂ അവലോകനം ചെയ്യുക. ഈ ചിത്രം ഉപയോഗിക്കുക തിരഞ്ഞെടുക്കുക. GHOSTWALK ഇപ്പോൾ അതിൻ്റെ ഉള്ളടക്കങ്ങൾ ഡീകോഡ് ചെയ്യും.","g_qr_img":"നിക്ഷേപത്തിനോ പേയ്‌മെൻ്റിനോ വേണ്ടി ആരെങ്കിലും നിങ്ങൾക്ക് QR കോഡ് അയച്ചാൽ, ചിത്രം ഇവിടെ അപ്‌ലോഡ് ചെയ്യുക. അതിൽ എന്താണ് അടങ്ങിയിരിക്കുന്നതെന്ന് കാണാൻ നിങ്ങളുടെ പേയ്‌മെൻ്റ് ആപ്ലിക്കേഷൻ ഉപയോഗിച്ച് നിങ്ങൾ ഇത് സ്കാൻ ചെയ്യേണ്ടതില്ല. ഡീകോഡ് ചെയ്ത ശേഷം, മറ്റെന്തെങ്കിലും ചെയ്യുന്നതിന് മുമ്പ് ലക്ഷ്യസ്ഥാനം അവലോകനം ചെയ്യുക.","g_qr_found":"QR-ൽ അടങ്ങിയിരിക്കുന്നത് ഇതാ. ഒന്നും കൊടുത്തില്ല, ഒന്നും തുറന്നില്ല.","sampleNote":"സാമ്പിൾ - പ്രകടനത്തിന് മാത്രം.","sampleJourneyNote":"നിയന്ത്രിത പ്രദർശന യാത്ര - സുരക്ഷിതമായ പരീക്ഷണ ലക്ഷ്യസ്ഥാനം, തത്സമയ ഭീഷണിയല്ല.","sampleQrNote":"സാമ്പിൾ QR - പ്രദർശനം മാത്രം. പേയ്‌മെൻ്റ് ആരംഭിച്ചിട്ടില്ല.","sampleCaseNote":"സാമ്പിൾ വീണ്ടെടുക്കൽ കേസ് - സാങ്കൽപ്പിക ഡെമോ ഡാറ്റ. വീണ്ടെടുക്കൽ ഒരിക്കലും ഉറപ്പില്ല.","sampleAlertText":"കൂടുതൽ സ്ഥിരീകരണം ആവശ്യമാണെന്ന് GHOSTWALK തിരിച്ചറിഞ്ഞ ഒരു നിക്ഷേപ അഭ്യർത്ഥന എനിക്ക് ലഭിച്ചു. ഞാൻ തുടരുന്നതിന് മുമ്പ്, നിങ്ങൾക്ക് ഇത് എന്നോടൊപ്പം അവലോകനം ചെയ്യാമോ?","sampleContact":"സാമ്പിൾ കോൺടാക്റ്റ്","packNeed":"ആദ്യം സംഭവിച്ചതിൻ്റെ ഒരു ഘട്ടമെങ്കിലും ചേർക്കുക.","carriedOver":"👻 നിങ്ങളുടെ വിശകലനത്തിൽ നിന്ന് എടുത്തത് - അവലോകനം ചെയ്ത് ഡ്രാഫ്റ്റ് അമർത്തുക.","explain":"വിശദീകരിക്കുക","readAloud":"ഉറക്കെ വായിക്കുക","notNow":"ഇപ്പോൾ വേണ്ട","resultsReady":"നിങ്ങളുടെ ഫലം ചുവടെ തയ്യാറാണ്. എന്നെ ടാപ്പുചെയ്യുക, ഞാൻ അത് ലളിതമായി വിശദീകരിക്കും.","uncertain":"ഞങ്ങൾക്ക് ഇത് വിശ്വസനീയമായി പരിശോധിക്കാൻ കഴിഞ്ഞില്ല. അത് സുരക്ഷിതമാണെന്ന് അർത്ഥമാക്കുന്നില്ല. നിങ്ങൾ അത് സ്വതന്ത്രമായി പരിശോധിക്കുന്നത് വരെ ദയവായി തുടരരുത്.","checking":"ചെക്ക് താഴെ പ്രവർത്തിക്കുന്നു. ഇത് ഒറ്റപ്പെടലിലാണ് ലക്ഷ്യസ്ഥാനം വായിക്കുന്നത്, അതിനാൽ നിങ്ങൾ സ്വയം ഒന്നും തൊടേണ്ടതില്ല.","understood":"മനസ്സിലായി. നിങ്ങൾക്ക് എന്നെ വേണമെങ്കിൽ ഞാൻ ഇവിടെയുണ്ട്.","noResult":"ആദ്യം ഒരു പരിശോധന നടത്തുക - അപ്പോൾ അത് കണ്ടെത്തിയതെന്താണെന്ന് എനിക്ക് കൃത്യമായി വിശദീകരിക്കാൻ കഴിയും.","m_index_t":"GHOSTWALK എന്താണ് ചെയ്യുന്നത്","m_index":["നിങ്ങൾക്ക് ലഭിക്കുന്നത് തിരഞ്ഞെടുക്കുക: സന്ദേശം, ലിങ്ക്, QR, വിശ്വസ്ത വ്യക്തി അല്ലെങ്കിൽ ഇതിനകം പണമടച്ച സഹായം.","നിങ്ങൾ ഒരിക്കലും സംശയാസ്പദമായ ലിങ്കുകൾ സ്വയം തുറക്കില്ല - പ്രേതം അവയെ സെർവർ സൈഡിലൂടെ നടത്തുന്നു.","നിങ്ങൾക്ക് എപ്പോഴെങ്കിലും നിർത്തുകയോ പരിശോധിച്ചുറപ്പിക്കുകയോ മാത്രമേ ലഭിക്കൂ. ഒരിക്കലും തെറ്റായ \"സുരക്ഷിതം\" അല്ല."],"m_message_t":"ഒരു സന്ദേശം പരിശോധിക്കുന്നു","m_message":["ടെക്സ്റ്റ് ടാബിൽ ചാറ്റ് ഒട്ടിച്ച് വിശകലനം അമർത്തുക.","ഫോട്ടോ ടാബ് സ്ക്രീൻഷോട്ടുകൾ വായിക്കുകയും മറഞ്ഞിരിക്കുന്ന QR കോഡുകൾ കണ്ടെത്തുകയും ചെയ്യുന്നു.","PDF ടാബ് ബ്രോഷറുകൾ വായിക്കുന്നു. ടൈപ്പുചെയ്യുന്നതിന് പകരം സംസാരിക്കാൻ വോയ്‌സ് ടാബ് നിങ്ങളെ അനുവദിക്കുന്നു."],"m_ghost_t":"ഒരു ലിങ്ക് നടത്തുന്നു","m_ghost":["സംശയാസ്പദമായ ലിങ്ക് ബോക്സിൽ ഒട്ടിക്കുക. ഇത് സ്വയം തുറക്കരുത്.","\"പ്രേതത്തെ അയയ്‌ക്കുക\" അമർത്തി താഴെയുള്ള റീപ്ലേ കാണുക.","പ്രേതം വ്യാജ വിശദാംശങ്ങൾ മാത്രമാണ് ഉപയോഗിക്കുന്നത് - ഒരിക്കലും നിങ്ങളുടേതല്ല."],"m_qr_t":"ഒരു QR / UPI വായിക്കുന്നു","m_qr":["QR-ന് പിന്നിൽ മറഞ്ഞിരിക്കുന്ന UPI സ്ട്രിംഗ് ഒട്ടിക്കുക - ഒരിക്കലും അത് സ്വയം സ്കാൻ ചെയ്യരുത്.","പണം യഥാർത്ഥത്തിൽ എവിടെ പോകുമെന്ന് പ്രേതം വായിക്കുന്നു.","കാണിച്ചിരിക്കുന്ന പേര് യഥാർത്ഥ കമ്പനിയുമായി പ്രത്യേകം താരതമ്യം ചെയ്യുക."],"m_trusted_t":"നിങ്ങൾ വിശ്വസിക്കുന്ന ഒരാളോട് ചോദിക്കുന്നു","m_trusted":["പേരും തുകയും പൂരിപ്പിക്കുക, തുടർന്ന് ഡ്രാഫ്റ്റ് അമർത്തുക.","വാട്ട്‌സ്ആപ്പിലെ ഹ്രസ്വ സന്ദേശം നിങ്ങളുടെ കുടുംബവുമായി പങ്കിടുക.","അവർ ഒന്നും അംഗീകരിക്കുന്നില്ല - അവർ നിങ്ങളോടൊപ്പം നിൽക്കുന്നു."],"m_recovery_t":"നിങ്ങൾ ഇതിനകം പണമടച്ചിട്ടുണ്ടെങ്കിൽ","m_recovery":["സംഭവിച്ചത് ഘട്ടം ഘട്ടമായി ചേർക്കുക.","\"Build my incident pack\" അമർത്തി അത് ഡൗൺലോഡ് ചെയ്യുക.","നിങ്ങളുടെ ബാങ്കിലേക്കും 1930 ഹെൽപ്പ്‌ലൈനിലേക്കും കൊണ്ടുപോകുക. തുടർന്നുള്ള എല്ലാ പേയ്‌മെൻ്റുകളും നിർത്തുക."],"understand":"എൻ്റെ ഫലം മനസ്സിലാക്കുക","saidRed":"ഇത് നിർത്തുക എന്ന് പറയുന്നു. പണമടയ്ക്കരുത്, OTP അല്ലെങ്കിൽ ബാങ്ക് വിശദാംശങ്ങൾ പങ്കിടരുത്.","saidYellow":"ഇത് പരിശോധിച്ചിട്ടില്ലെന്ന് പറയുന്നു. ഇതുവരെ പണം നൽകരുത്.","ai_title":"ഗോസ്റ്റ് AI","ai_assisted":"AI- സഹായത്തോടെയുള്ള വിശദീകരണം","ai_note":"ഈ കണ്ടെത്തൽ വിശദീകരിക്കാൻ ആവശ്യമായ വിവരങ്ങൾ മാത്രമാണ് ഗോസ്റ്റിന് ലഭിക്കുന്നത്. AI പ്രോസസ്സിംഗിന് മുമ്പ് സെൻസിറ്റീവ് വിശദാംശങ്ങൾ നീക്കം ചെയ്യപ്പെടും.","ai_why_data":"എന്തുകൊണ്ടാണ് AI-ക്ക് ഇത് വേണ്ടത്","ai_privacy":"സ്വകാര്യത","ai_p1":"കണ്ടെത്തലുകൾ വിശദീകരിക്കാനും ഈ ഇൻ്റർഫേസിലൂടെ നിങ്ങളെ നയിക്കാനും മാത്രമാണ് AI ഉപയോഗിക്കുന്നത്.","ai_p2":"എന്തെങ്കിലും പ്രോസസ്സ് ചെയ്യുന്നതിന് മുമ്പ് സെൻസിറ്റീവ് വിവരങ്ങൾ ചെറുതാക്കുകയും തിരുത്തുകയും ചെയ്യുന്നു.","ai_p3":"GHOSTWALK-ൽ ഒരിടത്തും OTP, പിൻ, പാസ്‌വേഡ് അല്ലെങ്കിൽ കാർഡ് സുരക്ഷാ കോഡ് എന്നിവ നൽകരുത്.","ai_p4":"ബാഹ്യ AI പ്രോസസ്സിംഗ് കോൺഫിഗർ ചെയ്‌തിരിക്കുന്നിടത്ത് മാത്രമേ നടക്കൂ, നിങ്ങൾ ചോദിച്ച വിശദീകരണത്തിന് വേണ്ടി മാത്രം.","ai_p5":"AI സഹായമില്ലാതെ നിങ്ങൾക്ക് എല്ലാ പ്രധാന GHOSTWALK ഫീച്ചറും ഉപയോഗിക്കാം.","ai_simple":"ലളിതമായി വിശദീകരിക്കുക","ai_why":"എന്തുകൊണ്ടാണ് ഇത് പ്രസക്തമാകുന്നത്?","ai_next":"ഞാൻ അടുത്തതായി എന്താണ് ചെയ്യേണ്ടത്?","ai_overview":"എന്താണ് കണ്ടെത്തിയതെന്ന് വിശദീകരിക്കുക","ai_working":"വിവർത്തനം ചെയ്യുന്നു...","ai_basic":"അന്തർനിർമ്മിത വിശദീകരണം കാണിക്കുന്നു","ai_unavail":"AI സഹായം ഇപ്പോൾ ലഭ്യമല്ല, പകരം ബിൽറ്റ്-ഇൻ വിശദീകരണം ഇതാ.","ai_src_ai":"AI- സഹായത്തോടെ","ai_src_basic":"അന്തർനിർമ്മിത","ai_privacy_short":"AI പ്രോസസ്സിംഗിന് മുമ്പ് സെൻസിറ്റീവ് വിശദാംശങ്ങൾ നീക്കം ചെയ്തു","ai_consent_q":"AI ഉപയോഗിച്ച് ഈ ഉള്ളടക്കം വിശദീകരിക്കാൻ, കണ്ടെത്തിയ സെൻസിറ്റീവ് വിവരങ്ങൾ നീക്കം ചെയ്തതിന് ശേഷം GHOSTWALK ടെക്സ്റ്റ് പ്രോസസ്സ് ചെയ്യേണ്ടതുണ്ട്. തുടരണോ?","ai_consent_yes":"തുടരുക","ai_consent_no":"പകരം അടിസ്ഥാന വിശകലനം ഉപയോഗിക്കുക","ai_offtopic":"ഞാൻ GHOSTWALK, തട്ടിപ്പ് സുരക്ഷ, നിക്ഷേപക സംരക്ഷണം എന്നിവയിൽ മാത്രം സഹായിക്കുന്നു. എനിക്ക് നിക്ഷേപങ്ങളോ ഓഹരികളോ ട്രേഡുകളോ ശുപാർശ ചെയ്യാൻ കഴിയില്ല.","ai_retry":"വീണ്ടും ശ്രമിക്കുക","ai_never":"OTP, പിൻ, പാസ്‌വേഡ് അല്ലെങ്കിൽ കാർഡ് സുരക്ഷാ കോഡ് എന്നിവ ആരുമായും പങ്കിടരുത്.","ai_missing_key":"ഈ വിശദീകരണം ഇതുവരെ നിങ്ങളുടെ ഭാഷയിൽ ലഭ്യമല്ല. GHOSTWALK-ൻ്റെ മറ്റെല്ലാ ഭാഗങ്ങളും ഇപ്പോഴും പ്രവർത്തിക്കുന്നു, പകരം എല്ലായ്‌പ്പോഴും ചുവടെയുള്ള അന്തർനിർമ്മിത ഉത്തരം കാണിക്കും.","ai_send_none":"ഈ വിശദീകരണത്തിനായി ഒരു AI ദാതാവിനും ഒന്നും അയച്ചിട്ടില്ല.","gd_red_simple":"GHOSTWALK അന്വേഷണത്തിനിടെ പ്രത്യേക മുന്നറിയിപ്പ് അടയാളങ്ങൾ നിരീക്ഷിച്ചു. അപകടകരമായ എന്തോ ഒന്ന് കണ്ടു, കൂടുതൽ മുന്നറിയിപ്പുകളുടെ അഭാവം സുരക്ഷയുടെ തെളിവല്ല.","gd_red_why":"നിരീക്ഷിച്ചത് തെളിയിക്കപ്പെട്ട കോടതി കേസായിട്ടല്ല, തെളിവായി രേഖപ്പെടുത്തുന്നു. പണം അയക്കുന്നതോ OTP പങ്കിടുന്നതോ പഴയപടിയാക്കാൻ കഴിയാത്തതിനാൽ, നിർത്തുന്നത് ന്യായീകരിക്കാൻ ഇത് മതിയാകും.","gd_red_next":"പണം അയയ്‌ക്കരുത്, OTP, പിൻ, പാസ്‌വേഡ് അല്ലെങ്കിൽ കാർഡ് സുരക്ഷാ കോഡ് എന്നിവ പങ്കിടരുത്. മറ്റെന്തെങ്കിലും ചെയ്യുന്നതിന് മുമ്പ്, ഈ സംഭാഷണത്തിന് പുറത്ത്, സ്ഥാപനത്തെ സ്വതന്ത്രമായി പരിശോധിക്കുക.","gd_yellow_simple":"GHOSTWALK-ന് ഈ യാത്രയിൽ വേണ്ടത്ര വിശ്വസിക്കാൻ കഴിഞ്ഞില്ല. അത് സുരക്ഷിതമാണെന്ന് അർത്ഥമാക്കുന്നില്ല, അത് വഞ്ചനയാണെന്ന് അർത്ഥമാക്കുന്നില്ല.","gd_yellow_why":"പരിശോധിച്ചിട്ടില്ല എന്നതിനർത്ഥം പരിശോധനകൾക്ക് ഒന്നും സ്ഥിരീകരിക്കാനോ നിരസിക്കാനോ കഴിഞ്ഞില്ല. സ്ഥിരീകരണമില്ലാതെ പ്രവർത്തിക്കുന്നതിൻ്റെ അപകടസാധ്യത പൂർണ്ണമായും നിങ്ങളുടേതാണ്.","gd_yellow_next":"ഈ സംഭാഷണത്തിന് പുറത്ത്, സ്ഥാപനം സ്വതന്ത്രമായി പരിശോധിച്ചുറപ്പിക്കുന്നതുവരെ പണം നൽകരുത്, വ്യക്തിഗത വിശദാംശങ്ങൾ പങ്കിടരുത്.","gd_none_simple":"ഇതുവരെ ഒന്നും പരിശോധിച്ചിട്ടില്ല, അതിനാൽ എനിക്ക് വിശദീകരിക്കാൻ ഒന്നുമില്ല.","gd_none_why":"ഒരു വിശദീകരണത്തിന് യഥാർത്ഥത്തിൽ എന്താണ് നിരീക്ഷിക്കപ്പെട്ടതെന്ന് മാത്രമേ വിവരിക്കാൻ കഴിയൂ. ഒരു പരിശോധന കൂടാതെ, ഏത് വിവരണവും ഊഹക്കച്ചവടമായിരിക്കും.","gd_none_next":"ആദ്യം ചെക്ക് റൺ ചെയ്യുക, എന്നിട്ട് അത് എന്താണ് കണ്ടെത്തിയതെന്ന് വിശദീകരിക്കാൻ എന്നോട് ആവശ്യപ്പെടുക.","gc_payment_destination_simple":"പരിശോധിച്ചുറപ്പിച്ച ഒരു ഓർഗനൈസേഷനുമായി GHOSTWALK പൊരുത്തപ്പെടാത്ത ഒരു പേയ്‌മെൻ്റ് വിലാസത്തിലേക്ക് പണം നിങ്ങളുടെ അക്കൗണ്ടിൽ നിന്ന് വിടും.","gc_payment_destination_why":"നിങ്ങളുടെ പണം സ്വീകരിക്കുന്ന വ്യക്തിയോ ബിസിനസ്സോ ആണ് പേയ്‌മെൻ്റ് വിലാസം. ഇത് സ്വതന്ത്രമായി പരിശോധിച്ചുറപ്പിക്കാൻ കഴിയാത്തതിനാൽ, ആരാണ് യഥാർത്ഥത്തിൽ പേയ്‌മെൻ്റ് സ്വീകരിക്കുന്നതെന്ന് സ്ഥിരീകരിക്കാൻ ഒരു മാർഗവുമില്ല.","gc_payment_destination_next":"ഇതുവരെ പണം നൽകരുത്. നിങ്ങൾ ഇതിനകം വിശ്വസിക്കുന്ന ഒരു വെബ്‌സൈറ്റോ ഫോൺ നമ്പറോ ഉപയോഗിച്ച് നിങ്ങളുടെ പേയ്‌മെൻ്റ് ആപ്പിൽ കാണിച്ചിരിക്കുന്ന പണമടയ്ക്കുന്നയാളുടെ പേര് ഔദ്യോഗിക സ്ഥാപനത്തിൻ്റെ പേരുമായി താരതമ്യം ചെയ്യുക.","gc_withdrawal_trap_simple":"നിങ്ങൾ ഇതിനകം തിരിച്ചയച്ച പണം ലഭിക്കുന്നതിന് മുമ്പ് മറ്റൊരു പേയ്‌മെൻ്റ് ആവശ്യപ്പെടുന്നു.","gc_withdrawal_trap_why":"നിയമാനുസൃതമായ പിൻവലിക്കലുകൾ ബാലൻസിൽ നിന്ന് ചാർജുകൾ കുറയ്ക്കുന്നു. ഫണ്ട് റിലീസ് ചെയ്യുന്നതിന് മുമ്പ് ഒരു പുതിയ പേയ്‌മെൻ്റിനുള്ള ഒരു പ്രത്യേക ആവശ്യം അറിയപ്പെടുന്ന ഒരു കെണിയാണ്, ആദ്യ പേയ്‌മെൻ്റ് സാധാരണയായി ഒരിക്കലും തിരികെ നൽകില്ല.","gc_withdrawal_trap_next":"തുടർന്നുള്ള എല്ലാ പേയ്‌മെൻ്റുകളും നിർത്തുക. ഫണ്ട് റിലീസ് ചെയ്യുന്നതിനായി ഫീസോ നികുതിയോ നിക്ഷേപമോ അയക്കരുത്. ഇതിനകം അയച്ച പണം നഷ്ടപ്പെട്ടതായി കണക്കാക്കി ഉടൻ നിങ്ങളുടെ ബാങ്കുമായി ബന്ധപ്പെടുക.","gc_redirect_identity_simple":"ഇവിടെ എത്തുന്നതിന് മുമ്പ് ലിങ്ക് നിങ്ങളെ മറ്റ് വെബ് വിലാസങ്ങളിലൂടെ നീക്കി, അതിനാൽ അവസാന പേജ് ലിങ്ക് ചൂണ്ടിക്കാണിക്കുന്നതല്ല.","gc_redirect_identity_why":"നിങ്ങൾ ക്ലിക്കുചെയ്ത ലിങ്കിൽ ദൃശ്യമായതൊന്നും മാറ്റാതെ നിങ്ങൾ കാണിക്കുന്നത് മാറ്റാനുള്ള അവസരമാണ് ഓരോ ഹോപ്പും. നിങ്ങൾ തുറന്നതായി കരുതുന്ന സ്ഥാപനം വ്യത്യസ്തമായ ഒന്നായിരിക്കാം.","gc_redirect_identity_next":"യാത്ര നിർത്തി ഈ പേജിൽ ഒന്നും നൽകരുത്. നിങ്ങൾക്ക് ഇതിനകം അറിയാവുന്ന ഒരു വിലാസം ടൈപ്പ് ചെയ്തുകൊണ്ട് ഔദ്യോഗിക വെബ്സൈറ്റ് സ്വയം തുറക്കുക, തുടർന്ന് ഓഫർ നിലവിലുണ്ടോയെന്ന് പരിശോധിക്കുക.","gc_lookalike_address_simple":"രേഖാമൂലമുള്ള വിലാസം ഒരു വിശ്വസനീയമായ സ്ഥാപനം പോലെയാണ് രൂപകൽപ്പന ചെയ്‌തിരിക്കുന്നത്, പക്ഷേ അത് ആ സ്ഥാപനമല്ല.","gc_lookalike_address_why":"പ്രതീകങ്ങൾ ദൃശ്യപരമായി സമാനമായവ ഉപയോഗിച്ച് മാറ്റിസ്ഥാപിക്കാം, അല്ലെങ്കിൽ @ ചിഹ്നത്തിന് മുമ്പായി വാചകം മറയ്‌ക്കാം, അതിനാൽ മറ്റെവിടെയെങ്കിലും ചൂണ്ടിക്കാണിക്കുന്ന സമയത്ത് വിലാസം ഒരു ബാങ്കോ ബ്രോക്കറോ പോലെ വായിക്കുന്നു.","gc_lookalike_address_next":"തുടരരുത്. നിങ്ങളുടെ ബാങ്ക് കാർഡിലെ നമ്പർ അല്ലെങ്കിൽ അതിൻ്റെ ഔദ്യോഗിക ആപ്പ് പോലുള്ള, നിങ്ങൾ ഇതിനകം വിശ്വസിക്കുന്ന ഒരു ചാനലിലൂടെ സ്ഥാപനം പരിശോധിച്ചുറപ്പിക്കുക. ഒരേ ചാറ്റിലോ ഒരേ പേജിലോ ഒരിക്കലും സ്ഥിരീകരിക്കരുത്.","gc_transport_security_simple":"ഈ പേജിലേക്കുള്ള കണക്ഷൻ സുരക്ഷിതമല്ല, അല്ലെങ്കിൽ അത് ആരാണെന്ന് തെളിയിക്കാൻ സൈറ്റിന് കഴിഞ്ഞില്ല.","gc_transport_security_why":"സാധുവായ ഒരു സർട്ടിഫിക്കറ്റ് ഇല്ലാതെ, കണക്ഷൻ പ്രവർത്തിപ്പിക്കുന്ന ആർക്കും നിങ്ങൾ ടൈപ്പുചെയ്യുന്നത് വായിക്കാനും മാറ്റാനും കഴിയും. മറ്റൊരു സൈറ്റിന് പേരുനൽകുന്ന ഒരു സർട്ടിഫിക്കറ്റ് അർത്ഥമാക്കുന്നത് പേജ് അത് ഉൾപ്പെടാത്ത എവിടെ നിന്നോ നൽകുന്നു എന്നാണ്.","gc_transport_security_next":"വ്യക്തിപരമോ സാമ്പത്തികമോ ആയ വിശദാംശങ്ങളൊന്നും നൽകരുത്. പേജ് ഉപേക്ഷിച്ച്, സ്വതന്ത്രമായി എത്തിച്ചേരുന്ന സ്ഥാപനത്തിൻ്റെ ഔദ്യോഗിക ആപ്പോ വെബ്‌സൈറ്റോ മാത്രം ഉപയോഗിക്കുക.","gc_credentials_request_simple":"നിയമാനുസൃത നിക്ഷേപ പേജിന് ആവശ്യമില്ലാത്ത വ്യക്തിപരമോ സാമ്പത്തികമോ ആയ വിശദാംശങ്ങൾ ഈ പേജ് ആവശ്യപ്പെട്ടിട്ടുണ്ട്.","gc_credentials_request_why":"ഒരു OTP, പാസ്‌വേഡ്, പിൻ അല്ലെങ്കിൽ കാർഡ് സുരക്ഷാ കോഡ് എന്നിവയ്ക്ക് പേയ്‌മെൻ്റുകൾ അംഗീകരിക്കാനോ നിങ്ങളുടെ അക്കൗണ്ടിലേക്ക് ആർക്കെങ്കിലും ആക്‌സസ് നൽകാനോ കഴിയും. ഒരു യഥാർത്ഥ പിന്തുണാ പ്രതിനിധിയും നിങ്ങളോട് ഒരെണ്ണം പങ്കിടാൻ ആവശ്യപ്പെടരുത്.","gc_credentials_request_next":"ഒന്നും പങ്കിടരുത്. നിങ്ങൾ ഇതിനകം ഒരു OTP അല്ലെങ്കിൽ പാസ്‌വേഡ് നൽകിയിട്ടുണ്ടെങ്കിൽ, പാസ്‌വേഡ് മാറ്റി നിങ്ങളുടെ ബാങ്കിനെ ഉടൻ വിളിക്കുക, തുടർന്ന് സൈബർ-ക്രൈം ഹെൽപ്പ്‌ലൈൻ 1930-ൽ റിപ്പോർട്ട് ചെയ്യുക.","gc_device_control_simple":"സ്‌ക്രീൻ പങ്കിടൽ അല്ലെങ്കിൽ നിങ്ങളുടെ ക്യാമറയിലേക്കും മൈക്രോഫോണിലേക്കും ആക്‌സസ്സ് പോലുള്ള നിങ്ങളുടെ ഉപകരണത്തിൻ്റെ നിയന്ത്രണം പേജ് ആവശ്യപ്പെട്ടു.","gc_device_control_why":"നിങ്ങളുടെ ബാങ്കിംഗ് ആപ്പിൽ ടൈപ്പ് ചെയ്യുന്നതെന്തും ഉൾപ്പെടെ, നിങ്ങൾ ചെയ്യുന്നതെല്ലാം കാണാനും നിങ്ങളുടെ താൽപ്പര്യാർത്ഥം ഡാറ്റ നൽകാനും വിദൂര ആക്‌സസ് മറ്റൊരു വ്യക്തിയെ അനുവദിക്കുന്നു.","gc_device_control_next":"അഭ്യർത്ഥന നിരസിച്ച് പേജ് അടയ്ക്കുക. നിങ്ങൾ പരിചയപ്പെടാത്ത ഒരാൾക്ക് വേണ്ടി ഒരിക്കലും റിമോട്ട് ആക്‌സസ് സോഫ്‌റ്റ്‌വെയർ ഇൻസ്റ്റാൾ ചെയ്യരുത്. നിങ്ങൾ ഇത് ഇതിനകം ഇൻസ്‌റ്റാൾ ചെയ്‌തിട്ടുണ്ടെങ്കിൽ, നിങ്ങളുടെ ഇൻ്റർനെറ്റ് സ്വിച്ച് ഓഫ് ചെയ്‌ത് നിങ്ങൾ വിശ്വസിക്കുന്ന ആരോടെങ്കിലും സഹായം ആവശ്യപ്പെടുക.","gc_app_install_simple":"ഔദ്യോഗിക സ്റ്റോറിന് പുറത്ത് നിന്ന് ഇൻസ്റ്റാൾ ചെയ്ത ഒരു ആപ്പിലേക്ക് നിങ്ങളെ നീക്കാൻ പേജ് ശ്രമിച്ചു.","gc_app_install_why":"ഈ രീതിയിൽ ഇൻസ്റ്റാൾ ചെയ്ത ആപ്പ് സ്റ്റോർ ചെക്കുകൾ ഒഴിവാക്കുകയും നിങ്ങളുടെ സന്ദേശങ്ങളും അറിയിപ്പുകളും ബാങ്കിംഗ് വിശദാംശങ്ങളും വായിക്കുകയും ചെയ്യും.","gc_app_install_next":"ഇത് ഇൻസ്റ്റാൾ ചെയ്യരുത്. ഇതിനകം ഡൗൺലോഡ് ചെയ്‌തതെന്തും ഇല്ലാതാക്കുക, നിങ്ങൾ സാധാരണയായി ഉപയോഗിക്കുന്ന സ്റ്റോറിൽ നിന്ന് അതിൻ്റെ ഔദ്യോഗിക ആപ്പ് വഴി മാത്രം സ്ഥാപനത്തിൽ എത്തിച്ചേരുക.","gc_new_domain_simple":"ഈ വെബ്‌സൈറ്റ് സൃഷ്ടിച്ചത് ദിവസങ്ങൾക്ക് മുമ്പാണ്.","gc_new_domain_why":"തട്ടിപ്പ് പ്രവർത്തനങ്ങൾ സാധാരണയായി വേഗത്തിൽ നിർമ്മിക്കുകയും വേഗത്തിൽ ഉപേക്ഷിക്കുകയും ചെയ്യുന്നു. ചരിത്രമില്ലാത്ത ഒരു സൈറ്റ് ഇപ്പോൾ മാറിയ ഒരു സ്ഥാപിത ഓർഗനൈസേഷനേക്കാൾ പുതിയതായിരിക്കാനുള്ള സാധ്യത വളരെ കൂടുതലാണ്.","gc_new_domain_next":"ഓഫർ പരിശോധിച്ചുറപ്പിക്കാത്തതായി പരിഗണിക്കുക. ഈ ലിങ്ക് ഉപയോഗിക്കാതെ തന്നെ നിങ്ങൾക്ക് എത്തിച്ചേരാൻ കഴിയുന്ന ഒരു ഔദ്യോഗിക വെബ്‌സൈറ്റോ ആപ്പോ രജിസ്ട്രേഷനോ സ്ഥാപനത്തിന് ഉണ്ടോയെന്ന് പരിശോധിക്കുക.","gc_pressure_simple":"പേജോ സന്ദേശമോ നിങ്ങളെ ഇപ്പോൾ പ്രവർത്തിക്കാൻ സമയ സമ്മർദ്ദം ചെലുത്തുന്നു.","gc_pressure_why":"നിങ്ങൾ വിശ്വസിക്കുന്ന ഒരാളോട് ചിന്തിക്കുന്നതിനോ ചോദിക്കുന്നതിനോ നിങ്ങളെ തടയുന്നതിനാണ് സമ്മർദ്ദം രൂപകൽപ്പന ചെയ്തിരിക്കുന്നത്. ഒരു യഥാർത്ഥ നിക്ഷേപ അവസരം നാളെയും നിലവിലുണ്ട്, എന്നാൽ ഒരു കൗണ്ട്ഡൗൺ സാധാരണയായി ഉണ്ടാകില്ല.","gc_pressure_next":"നിർത്തി കാത്തിരിക്കുക. പേജ് അടയ്‌ക്കുക, തുടർന്ന് എന്തെങ്കിലും ചെയ്യുന്നതിനുമുമ്പ് സ്ഥാപനം സ്വതന്ത്രമായി പരിശോധിക്കുക.","gc_deception_simple":"പേജ് മറ്റുള്ളവരുടെ വിജയം തെളിവായി ഉപയോഗിച്ചു, അല്ലെങ്കിൽ കാര്യം രഹസ്യമായി സൂക്ഷിക്കാൻ നിങ്ങളോട് ആവശ്യപ്പെട്ടു.","gc_deception_why":"ലാഭത്തിൻ്റെ സ്‌ക്രീൻഷോട്ടുകൾ കെട്ടിച്ചമയ്ക്കാൻ എളുപ്പമാണ്, രഹസ്യസ്വഭാവം ആവശ്യപ്പെടുന്നത് പ്രവർത്തിക്കുന്ന ഒരു പരിരക്ഷയെ ഇല്ലാതാക്കുന്നു: നിങ്ങളെ അറിയുന്ന ഒരാളിൽ നിന്നുള്ള രണ്ടാമത്തെ അഭിപ്രായം.","gc_deception_next":"സാക്ഷ്യപത്രങ്ങളെ ആശ്രയിക്കരുത്. ഓഫർ പ്രവർത്തിക്കുന്നതിന് മുമ്പ്, ഈ സംഭാഷണത്തിന് പുറത്ത് നിങ്ങൾക്ക് വിശ്വാസമുള്ള ഒരാളെ കാണിക്കുക.","gc_off_channel_simple":"സംഭാഷണം ഒരു സ്വകാര്യ ചാറ്റ് ആപ്ലിക്കേഷനിലേക്കോ സ്ക്രീൻ പങ്കിടലിലേക്കോ നീക്കി.","gc_off_channel_why":"സ്വകാര്യ ചാനലുകൾ നിങ്ങൾക്ക് മടങ്ങിവരാൻ കഴിയുന്ന ഒരു റെക്കോർഡും അവശേഷിപ്പിക്കുന്നില്ല, നിങ്ങൾ സംസാരിക്കുന്ന വ്യക്തിയെ ഇനി ഏതെങ്കിലും ഔദ്യോഗിക ചാനലിനെതിരെ പരിശോധിക്കാനാകില്ല.","gc_off_channel_next":"സംഭാഷണം ഒരു ഔദ്യോഗിക ചാനലിലേക്ക് തിരികെ നീക്കുക, അല്ലെങ്കിൽ നിർത്തുക. ഒരു സ്വകാര്യ ചാറ്റ് ആപ്ലിക്കേഷനിൽ തുടരരുത്.","gc_escalation_simple":"ആവശ്യപ്പെടുന്ന തുക വർദ്ധിച്ചുകൊണ്ടിരിക്കുന്നു, ഗ്യാരണ്ടീഡ് അല്ലെങ്കിൽ അസാധാരണമായ ഉയർന്ന റിട്ടേൺ വാഗ്ദാനം ചെയ്തു.","gc_escalation_why":"യഥാർത്ഥ നിക്ഷേപങ്ങൾ എല്ലായ്പ്പോഴും റിസ്ക് വഹിക്കുന്നു, ഒരിക്കലും ലാഭം ഉറപ്പുനൽകുന്നില്ല. ചെറുതായി തുടങ്ങുകയും പിന്നീട് വളരുകയും ചെയ്യുന്ന ഒരു പാറ്റേൺ രൂപകൽപ്പന ചെയ്‌തിരിക്കുന്നത് നിങ്ങൾക്ക് നഷ്ടപ്പെടാൻ പോകുന്ന കാര്യങ്ങൾ വർദ്ധിപ്പിക്കുന്നതിനാണ്.","gc_escalation_next":"അടുത്ത പേയ്മെൻ്റ് നടത്തരുത്. ഗ്യാരണ്ടീഡ് റിട്ടേൺ ആണ് അവിടെയുള്ള ഏറ്റവും വ്യക്തമായ മുന്നറിയിപ്പ് അടയാളം.","gc_unreachable_simple":"ഒരു പ്രാവശ്യം പോലും ലക്ഷ്യസ്ഥാനം ലോഡുചെയ്യാൻ കഴിയാത്തതിനാൽ അതിനെക്കുറിച്ച് ഒന്നും പരിശോധിക്കാനായില്ല.","gc_unreachable_why":"വിശ്വസനീയമായി ലോഡ് ചെയ്യാത്ത ഒരു വിലാസം പരിശോധിക്കാൻ കഴിയില്ല. അത് തെളിവുകളുടെ അഭാവമാണ്, സുരക്ഷയുടെ തെളിവല്ല.","gc_unreachable_next":"ഓഫർ പരിശോധിച്ചുറപ്പിക്കാത്തതായി കണക്കാക്കുക, പണം നൽകരുത്. ഇത് നിങ്ങൾക്കായി പ്രവർത്തിച്ചുവെന്നത് സുരക്ഷിതമാണെന്ന് അർത്ഥമാക്കുന്നില്ല.","gc_third_party_content_simple":"ഈ പേജ് ഒരു വെബ്സൈറ്റായി പ്രവർത്തിക്കുന്നില്ല. പല ബാഹ്യ സേവനങ്ങളിൽ നിന്നും ഇത് ഒരുമിച്ച് ചേർത്തിരിക്കുന്നു.","gc_third_party_content_why":"നിരവധി ബാഹ്യ സേവനങ്ങളിൽ നിന്ന് ഒരു പേജ് നിർമ്മിക്കുമ്പോൾ, അവയിലൊന്ന് നിങ്ങൾ കാണുന്നത് മാറ്റാൻ കഴിയും, അവയൊന്നും നിങ്ങളോട് ഉത്തരവാദിത്തമുള്ളവരല്ല.","gc_third_party_content_next":"ഈ പേജിൽ ഒന്നും നൽകരുത്. സ്വതന്ത്രമായി കണ്ടെത്തിയ സ്വന്തം വെബ്‌സൈറ്റ് അല്ലെങ്കിൽ ആപ്പ് വഴി സ്ഥാപനത്തിൽ എത്തിച്ചേരുക.","gc_unverified_simple":"GHOSTWALK ഈ നിരീക്ഷണം രേഖപ്പെടുത്തി, പക്ഷേ അതിന് ഇതുവരെ ഒരു പ്ലെയിൻ ഭാഷയിലുള്ള വിശദീകരണം ലഭിച്ചിട്ടില്ല.","gc_unverified_why":"നിരീക്ഷണം തെളിവായി രേഖപ്പെടുത്തിയിട്ടുണ്ട്. ഇത് കൂടുതൽ പരിശോധിച്ചിട്ടില്ല, അതിനാൽ അതിൽ നിന്ന് ഒരു നിഗമനത്തിലും എത്തിച്ചേരേണ്ടതില്ല.","gc_unverified_next":"ഇക്കാരണത്താൽ പണമടയ്ക്കുകയോ വ്യക്തിഗത വിവരങ്ങൾ പങ്കിടുകയോ ചെയ്യരുത്. പരിശോധന വീണ്ടും റൺ ചെയ്യുക അല്ലെങ്കിൽ സ്ഥാപനം സ്വതന്ത്രമായി പരിശോധിക്കുക."};
